@namespace sv_0c1ea80c201f4a9bb6bd1e24308fdfe5.Components.Pages.Settings

<nav class="nav nav-pills flex-column settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="nav-link text-start @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
            <span class="me-2">@GetIcon(section)</span>@section
        </button>
    }
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_0c1ea80c201f4a9bb6bd1e24308fdfe5.Components.Pages.Settings
@using sv_0c1ea80c201f4a9bb6bd1e24308fdfe5.Services

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Profile Settings</h4>

        <div class="row mb-4">
            <div class="col-md-3 text-center">
                <img src="@AvatarUrl" alt="Avatar" class="rounded-circle mb-2" style="width:100px;height:100px;object-fit:cover;" />
                <div class="text-muted small text-truncate">@AvatarUrl</div>
            </div>
            <div class="col-md-9">
                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="DisplayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="Email" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Avatar URL</label>
                    <input type="url" class="form-control" @bind="AvatarUrl" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="3" @bind="Bio"></textarea>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = null"></button>
            </div>
        }

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
                @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private string? _message;
    private bool _saving;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_saving)
        {
            LoadFromProfile(Profile);
        }
    }

    private void LoadFromProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        AvatarUrl = profile.AvatarUrl;
        Bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _message = "Profile saved successfully!";
    }

    private void DiscardChanges()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        _message = null;
    }
}

