        <h4 class="card-title mb-4">Appearance Settings</h4>

        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="mb-4">
                    <h6>Theme</h6>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{theme}")" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h6>Font Size</h6>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h6>Language</h6>
                    <select class="form-select" style="max-width:250px;" @bind="_language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                @if (!string.IsNullOrEmpty(_message))
                {
                    <div class="alert alert-success">@_message</div>
                }

                <button class="btn btn-primary" @onclick="Save" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save
                </button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <h6>Preview</h6>
                <div class="border rounded p-3 @GetPreviewClasses()" style="@GetPreviewStyles()">
                    <h6 style="@GetPreviewFontStyle()">Sample Heading</h6>
                    <p style="@GetPreviewFontStyle()" class="@(_compactMode ? "mb-1" : "mb-3")">
                        This is how your content will look with the selected settings.
                    </p>
                    <button class="btn btn-sm btn-primary">Sample Button</button>
                    <div class="mt-2 text-muted small" style="@GetPreviewFontStyle()">
                        Language: @_language | Compact: @(_compactMode ? "On" : "Off")
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private string? _message;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_saving)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private async Task Save()
    {
        _saving = true;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _message = "Appearance settings saved!";
    }

    private string GetPreviewClasses()
    {
        return _theme switch
        {
            "Dark" => "bg-dark text-light",
            _ => "bg-light text-dark"
        };
    }

    private string GetPreviewStyles()
    {
        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1rem;";
        return $"min-height: 150px; {padding}";
    }

    private string GetPreviewFontStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "font-size: 0.85rem;",
            "Large" => "font-size: 1.2rem;",
            _ => "font-size: 1rem;"
        };
        return size;
    }
}

@page "/settings"
@using sv_0c1ea80c201f4a9bb6bd1e24308fdfe5.Services
@using sv_0c1ea80c201f4a9bb6bd1e24308fdfe5.Components.Pages.Settings
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <h2 class="mb-4">Settings</h2>
    <div class="row">
        <!-- Sidebar -->
        <div class="col-md-3 col-lg-2 mb-3">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />
        </div>

        <!-- Main Content -->
        <div class="col-md-9 col-lg-10">
            @if (_loading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (_activeSection)
                {
                    case "Profile":
                        <ProfileSection Profile="@_profile" OnSave="SaveProfile" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotifications" />
                        break;
                    case "Security":
                        <SecuritySection Security="@_security"
                                         OnChangePassword="HandleChangePassword"
                                         OnRevokeSession="HandleRevokeSession"
                                         OnToggle2FA="HandleToggle2FA" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="@_appearance" OnSave="SaveAppearance" />
                        break;
                }
            }
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private bool _loading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadCurrentSection();
        _loading = false;
    }

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        _loading = true;
        await LoadCurrentSection();
        _loading = false;
    }

    private async Task LoadCurrentSection()
    {
        switch (_activeSection)
        {
            case "Profile":
                _profile = await SettingsService.GetProfileAsync();
                break;
            case "Notifications":
                _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security":
                _security = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                _appearance = await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfile(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task HandleChangePassword(string passwords)
    {
        var parts = passwords.Split('|');
        await SettingsService.ChangePasswordAsync(parts[0], parts[1]);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private Task HandleToggle2FA(bool enabled)
    {
        // In a real app this would call a service method
        return Task.CompletedTask;
    }

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
    }
}

